"""Independent brute-force solvers and tests for the 3-SAT -> Vertex Cover reduction."""
import itertools
import json
import random

from problems import ThreeSat, VertexCover
import reduce as reduce_module


# ---------------------------------------------------------------- solvers
def solve_three_sat(instance):
    """Brute force over all assignments of variables 1..num_vars."""
    m = instance["num_vars"]
    clauses = instance["clauses"]
    for bits in itertools.product([False, True], repeat=m):
        # bits[v-1] is the value of variable v
        ok = True
        for clause in clauses:
            if not any((bits[abs(l) - 1] if l > 0 else not bits[abs(l) - 1])
                       for l in clause):
                ok = False
                break
        if ok:
            return True
    return False


def solve_vertex_cover(instance):
    """Brute force: is there a vertex cover of size <= k?"""
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    if not edges:
        return k >= 0
    if k >= n:
        return True
    for size in range(0, k + 1):
        for subset in itertools.combinations(range(n), size):
            chosen = set(subset)
            if all(u in chosen or v in chosen for u, v in edges):
                return True
    return False


# ---------------------------------------------------------------- generators
def all_clauses_over(m):
    """All 3-literal clauses over 3 distinct variables from 1..m."""
    out = []
    for vars_ in itertools.combinations(range(1, m + 1), 3):
        for signs in itertools.product([1, -1], repeat=3):
            out.append([s * v for s, v in zip(signs, vars_)])
    return out


def random_three_sat(rng, max_vars=4, max_clauses=6):
    m = rng.randint(0, max_vars)
    clauses = []
    if m >= 3:
        pool = all_clauses_over(m)
        for _ in range(rng.randint(0, max_clauses)):
            clauses.append(list(rng.choice(pool)))
    return {"num_vars": m, "clauses": clauses}


def enumerate_small_instances():
    """Exhaustive-ish small instances plus hand-picked edge cases."""
    instances = []
    # no clauses, various m
    for m in range(0, 4):
        instances.append({"num_vars": m, "clauses": []})
    # all formulas with up to 2 clauses over m=3
    pool3 = all_clauses_over(3)
    for m in (3,):
        instances.append({"num_vars": m, "clauses": []})
        for c in pool3:
            instances.append({"num_vars": m, "clauses": [list(c)]})
        for c1 in pool3:
            for c2 in pool3:
                instances.append({"num_vars": m, "clauses": [list(c1), list(c2)]})
    # the classic unsat 4-clause formula over 3 vars
    instances.append({"num_vars": 3, "clauses": [
        [1, 2, 3], [-1, -2, 3], [-1, 2, -3], [1, -2, -3]]})
    # all 8 clauses -> unsat
    instances.append({"num_vars": 3, "clauses": [list(c) for c in pool3]})
    # duplicate clauses
    instances.append({"num_vars": 3, "clauses": [[1, 2, 3], [1, 2, 3]]})
    return instances


def main():
    rng = random.Random(12345)
    instances = enumerate_small_instances()
    # random instances
    for _ in range(400):
        instances.append(random_three_sat(rng, max_vars=4, max_clauses=6))

    tests_run = 0
    tests_passed = 0
    failures = []

    for inst in instances:
        # validate source
        try:
            ThreeSat.validate(inst)
        except Exception as e:
            failures.append(("invalid source", inst, repr(e)))
            continue

        reduced = reduce_module.reduce(inst)
        try:
            VertexCover.validate(reduced)
        except Exception as e:
            tests_run += 1
            failures.append(("invalid target", inst, repr(e)))
            continue

        src = solve_three_sat(inst)
        tgt = solve_vertex_cover(reduced)
        tests_run += 1
        if src == tgt:
            tests_passed += 1
        else:
            failures.append(("mismatch", inst, {"source": src, "target": tgt,
                                                "reduced": reduced}))

    print(json.dumps({
        "tests_run": tests_run,
        "tests_passed": tests_passed,
        "num_failures": len(failures),
        "sample_failures": [
            {"kind": k, "instance": i, "detail": d} for k, i, d in failures[:3]
        ],
    }, indent=2, default=str))


if __name__ == "__main__":
    main()
